/**
 * A QR code as an image, for drawing onto a canvas — MTC-FCS-040.
 * ============================================================================
 * `qr-code-styling` touches `document` the moment it is constructed, so it is
 * imported inside the function rather than at the top of the file. A static
 * import would run during Gatsby's server-side render and take the build down.
 *
 * ── WHY THE PLAIN LOOK ─────────────────────────────────────────────────────
 * Square dots, black on white, error correction H. This code gets photographed
 * off somebody else's phone screen in a Facebook group — resampled twice,
 * often at an angle, sometimes with a thumb over a corner. Rounded dots and a
 * brand colour cost contrast, and the whole thing is worthless if it does not
 * scan on the first try.
 */

/**
 * Renders `value` and resolves an HTMLImageElement ready for drawImage.
 *
 * @param {string} value  the URL the code points at
 * @param {number} size   pixels — 1024 by default, because the code is drawn
 *                        into an advert at up to ~280px and scaling a small QR
 *                        up is what makes the modules blur into each other
 */
export async function makeQrImage(value, size = 1024) {
  if (typeof window === "undefined") return null
  const text = String(value || "").trim()
  if (!text) return null

  const { default: QRCodeStyling } = await import("qr-code-styling")

  const qr = new QRCodeStyling({
    width: size,
    height: size,
    type: "canvas",
    data: text,
    margin: Math.round(size * 0.04),
    qrOptions: { errorCorrectionLevel: "H" },
    dotsOptions: { type: "square", color: "#0d2340" },
    cornersSquareOptions: { type: "square", color: "#0d2340" },
    cornersDotOptions: { type: "square", color: "#ea580c" },
    backgroundOptions: { color: "#ffffff" },
  })

  const blob = await qr.getRawData("png")
  if (!blob) return null

  const url = URL.createObjectURL(blob)
  try {
    return await new Promise((resolve, reject) => {
      const img = new Image()
      img.onload = () => resolve(img)
      img.onerror = reject
      img.src = url
    })
  } finally {
    // Revoked after the image has decoded; the bitmap survives the URL.
    setTimeout(() => URL.revokeObjectURL(url), 2000)
  }
}

/** Loads any same-origin image for the canvas. Resolves null rather than throwing. */
export function loadImage(src) {
  if (typeof window === "undefined" || !src) return Promise.resolve(null)
  return new Promise(resolve => {
    const img = new Image()
    // Same-origin assets only (see static/ads). A cross-origin photograph
    // without CORS headers taints the canvas and makes the export throw —
    // which would look like a broken download button.
    img.onload = () => resolve(img)
    img.onerror = () => resolve(null)
    img.src = src
  })
}
